const wmItems = await browserjs(2017691888, () => {
  const links = Array.from(document.querySelectorAll("a[href*='/ip/']"));
  const seen = new Set();
  const list = [];
  for (const a of links) {
    const title = a.innerText.trim();
    const href = a.href;
    if (title && title.length > 10 && !seen.has(href)) {
      seen.add(href);
      // find price container near this link
      let parent = a.closest("[data-item-id]") || a.parentElement;
      while (parent && !parent.innerText.includes('$') && parent !== document.body) {
        parent = parent.parentElement;
      }
      const priceMatch = parent?.innerText?.match(/\$\d+(\.\d{2})?/);
      list.push({
        title,
        href,
        price: priceMatch ? priceMatch[0] : null
      });
    }
  }
  return list;
});

console.log("Walmart items count:", wmItems.length);
